<p class="eyebrow">Compliance</p><h1>KYC configuration</h1><section class="card"><p>Each Country Pack—including Global—has an independent KYC requirement and versioned form.</p><form method="post" action="<?= e(route('admin.kyc.config.save')) ?>" class="form-stack"><?= app('csrf')->input() ?><label>Country Pack<select name="country_id"><?php foreach($countries as $country): ?><option value="<?= e($country['id']) ?>"><?= e($country['name']) ?></option><?php endforeach; ?></select></label><label>KYC form<select name="form_id"><option value="">No form configured</option><?php foreach($forms as $form): ?><option value="<?= e($form['id']) ?>"><?= e($form['name']) ?></option><?php endforeach; ?></select></label><label><input type="checkbox" name="is_required" value="1"> KYC required before withdrawals</label><label>Instructions<textarea name="instructions"></textarea></label><button class="button">Publish configuration version</button></form></section>
